from __future__ import annotations

import dataclasses
import typing
import pytest

import llm_router
import llm_router._internal.providers.retry as _retry_mod
from llm_router._internal.providers.retry import (
    build_provider_retrying,
    is_retryable_provider_error,
)

pytestmark = pytest.mark.verification_kind("unit")


class _TestLogger:
    def __call__(self, *args: typing.Any, **kwargs: typing.Any) -> typing.Any:
        return self

    def __getattr__(self, name: str) -> typing.Any:
        return self


def _build_policy(max_attempts: int = 3) -> typing.Any:
    policy_cls = getattr(_retry_mod, "RetryPolicy", None) or getattr(
        llm_router, "RetryPolicy", None
    )
    if policy_cls is not None:
        try:
            return policy_cls(
                max_attempts=max_attempts,
                min_wait_seconds=0.0,
                max_wait_seconds=0.0,
            )
        except TypeError:
            try:
                policy = policy_cls(max_attempts=max_attempts)
                policy.min_wait_seconds = 0.0
                policy.max_wait_seconds = 0.0
                return policy
            except TypeError:
                policy = policy_cls()
                policy.max_attempts = max_attempts
                policy.min_wait_seconds = 0.0
                policy.max_wait_seconds = 0.0
                return policy

    @dataclasses.dataclass
    class _FallbackRetryPolicy:
        max_attempts: int = max_attempts
        min_wait_seconds: float = 0.0
        max_wait_seconds: float = 0.0

    return _FallbackRetryPolicy(max_attempts=max_attempts)


def _find_retryable_error() -> Exception:
    globals_dict = is_retryable_provider_error.__globals__

    candidate_types: list[type[BaseException]] = []
    for val in globals_dict.values():
        if isinstance(val, (tuple, list, set)):
            for item in val:
                if isinstance(item, type) and issubclass(item, BaseException):
                    candidate_types.append(item)
        elif isinstance(val, type) and issubclass(val, BaseException):
            candidate_types.append(val)

    for name in dir(llm_router):
        val = getattr(llm_router, name)
        if isinstance(val, type) and issubclass(val, BaseException):
            candidate_types.append(val)

    trial_kwargs: list[dict[str, typing.Any]] = [
        {},
        {"message": "rate limit exceeded"},
        {"status_code": 429},
        {"status_code": 503},
        {"message": "rate limit exceeded", "status_code": 429},
        {"message": "temporary outage", "status_code": 503},
        {"retryable": True},
        {"is_retryable": True},
    ]
    trial_args: list[tuple[typing.Any, ...]] = [
        ("provider rate limit exceeded",),
        ("temporary provider outage",),
        ("error", 429),
        ("error", 503),
        (),
    ]

    for cls in candidate_types:
        for args in trial_args:
            for kwargs in trial_kwargs:
                try:
                    err = cls(*args, **kwargs)
                    if is_retryable_provider_error(err):
                        return err
                except Exception:
                    continue

    class RetryableProviderError(Exception):
        status_code = 429
        retryable = True
        is_retryable = True

    err = RetryableProviderError("provider temporarily unavailable")
    if is_retryable_provider_error(err):
        return err

    raise RuntimeError("Unable to construct a retryable provider error")


@pytest.mark.verifies("TREQ_PROVIDER_RETRY_BOUNDS[revision==1]")
def test_sync_exhausted_retry_surfaces_provider_error_and_respects_bounds() -> None:
    max_attempts = 3
    policy = _build_policy(max_attempts=max_attempts)
    logger = getattr(_retry_mod, "logger", None) or _TestLogger()

    retrying = build_provider_retrying(
        policy=policy,
        logger=logger,
    )

    target_error = _find_retryable_error()
    assert is_retryable_provider_error(target_error) is True

    call_count = 0

    def failing_provider_call() -> None:
        nonlocal call_count
        call_count += 1
        raise target_error

    with pytest.raises(BaseException) as exc_info:
        retrying(failing_provider_call)

    assert call_count == max_attempts
    assert exc_info.value is target_error
    assert type(exc_info.value) is type(target_error)
    assert type(exc_info.value).__name__ != "RetryError"
